import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
const root=path.resolve(import.meta.dirname,'..'),out=path.join(root,'dist');
const BASE='https://businessownerindex.com',AE='https://www.aetaxadvisors.com',BOOK=AE+'/discovery?utm_source=businessownerindex&utm_medium=directory&utm_campaign=owner_advisory';
const all=JSON.parse(fs.readFileSync(path.join(root,'data/owners.json'),'utf8'));
const owners=all.filter(p=>p.status==='published');
const guides=JSON.parse(fs.readFileSync(path.join(root,'data/guides.json'),'utf8'));
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const slug=s=>s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const json=x=>JSON.stringify(x).replace(/</g,'\\u003c');
const initials=s=>s.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('');
const industries=[...new Set(owners.map(x=>x.industry))].sort();
const locations=[...new Set(owners.map(x=>x.location).filter(x=>x!=='United States'))].sort();
const pages=[];
fs.rmSync(out,{recursive:true,force:true});fs.mkdirSync(path.join(out,'assets'),{recursive:true});
for(const file of fs.readdirSync(path.join(root,'assets')))fs.copyFileSync(path.join(root,'assets',file),path.join(out,'assets',file));
const logo=`<a class="brand" href="/" aria-label="Business Owner Index home"><img src="/assets/favicon.svg" alt="" width="42" height="42"><span class="brand-text">Business Owner<span>Index.</span></span></a>`;
function nav(p){const current=part=>p.startsWith(part)?' aria-current="page"':'';return `<a class="skip" href="#main">Skip to content</a><div class="announcement">A national directory of established founders · Owned and published by <a href="/ae-tax-advisors/">AE Tax Advisors</a></div><header class="header"><div class="wrap nav">${logo}<button class="nav-button" data-menu aria-expanded="false" aria-controls="site-nav">Menu</button><nav class="nav-links" id="site-nav" data-nav aria-label="Main navigation"><a href="/directory/"${current('/directory/')}>The directory</a><a href="/industries/"${current('/industries/')}>Industries</a><a href="/resources/"${current('/resources/')}>Owner resources</a><a href="/about/"${current('/about/')}>Our purpose</a><a class="button" href="/get-featured/">Get featured <span aria-hidden="true">↗</span></a></nav></div></header>`;}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-top"><div>${logo}<p>A record of the people building established businesses. Publicly sourced founder profiles, useful company context, and resources for the next chapter.</p></div><div><h3>Explore the index</h3><div class="footer-links"><a href="/directory/">Business owner directory</a><a href="/industries/">Browse by industry</a><a href="/locations/">Browse by location</a><a href="/get-featured/">Nominate or update a profile</a><a href="/people/">People A–Z</a><a href="/business-promotion/">Business promotion resources</a><a href="/sitemap/">All pages</a></div></div><div><h3>Behind the index</h3><div class="footer-links"><a href="/ae-tax-advisors/">Owned and published by AE Tax Advisors</a><a href="/tax-strategists/">Featured tax strategist</a><a href="/resources/">Owner planning library</a><a href="/editorial-standards/">Editorial standards</a><a href="/privacy/">Privacy</a><a href="/terms/">Terms & disclosures</a></div></div></div><div class="footer-bottom"><span>© ${new Date().getUTCFullYear()} Business Owner Index. Owned and published by AE Tax Advisors.</span><span>Business owners. Their companies. Their stories.</span></div><p class="footer-disclosure">Profiles based on public sources are identified as publicly researched. Inclusion does not establish current ownership, imply an AE client relationship, or constitute an endorsement. Revenue eligibility refers to a stated historical period, not current revenue or personal income. AE resources are general educational information; applicability depends on the facts and an engagement.</p></div></footer>`;}
const button=(url,label,type='')=>`<a class="button ${type}" href="${e(url)}">${e(label)} <span aria-hidden="true">↗</span></a>`;
function bread(items){return `<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a>${items.map(([label,url])=>`<span aria-hidden="true">/</span>${url?`<a href="${url}">${e(label)}</a>`:`<span aria-current="page">${e(label)}</span>`}`).join('')}</nav>`;}
function breadcrumbSchema(items){return {'@type':'BreadcrumbList',itemListElement:[['Home','/'],...items].map(([name,url],i)=>({'@type':'ListItem',position:i+1,name,item:BASE+url}))};}
function write(p,title,desc,body,opts={}){const dir=p==='/'?out:path.join(out,p);fs.mkdirSync(dir,{recursive:true});const indexable=opts.indexable!==false;const data=[{'@context':'https://schema.org','@type':'WebPage','@id':BASE+p+'#page',url:BASE+p,name:title,description:desc,isPartOf:{'@id':BASE+'/#website'},publisher:{'@type':'Organization','@id':BASE+'/#publisher',name:'Business Owner Index',url:BASE,parentOrganization:{'@type':'Organization','@id':AE+'/#organization',name:'AE Tax Advisors',url:AE}},...opts.webPage},...(opts.schema||[]).map(x=>({'@context':'https://schema.org',...x}))];const html=`<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(title)} | Business Owner Index</title><meta name="description" content="${e(desc)}"><meta name="robots" content="${indexable?'index,follow,max-image-preview:large':'noindex,follow'}"><meta name="theme-color" content="#193a30"><link rel="canonical" href="${BASE+p}"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="stylesheet" href="/assets/site.css"><meta property="og:type" content="${opts.article?'article':'website'}"><meta property="og:site_name" content="Business Owner Index"><meta property="og:title" content="${e(title)}"><meta property="og:description" content="${e(desc)}"><meta property="og:url" content="${BASE+p}"><meta property="og:image" content="${BASE}/assets/share.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${e(title)}"><meta name="twitter:description" content="${e(desc)}"><meta name="twitter:image" content="${BASE}/assets/share.png"><script type="application/ld+json">${json(data)}</script><script src="/assets/site.js" defer></script></head><body>${nav(p)}<main id="main">${body}</main>${footer()}</body></html>`;fs.writeFileSync(path.join(dir,'index.html'),html);if(indexable)pages.push({path:p,title,lastmod:opts.lastmod||'2026-10-09'});}
function card(p,i){return `<article class="owner-card"><a class="card-visual" data-theme="${i%5}" href="/owners/${p.slug}/" aria-label="View ${e(p.name)} profile"><span class="card-tag">Founder profile</span><span class="monogram" aria-hidden="true">${e(initials(p.name))}</span></a><div class="card-body"><span class="eyebrow">${e(p.industry)}</span><h3><a href="/owners/${p.slug}/">${e(p.name)}</a></h3><a class="company-name" href="/companies/${p.companySlug}/">${e(p.company)}</a><p class="card-summary">${e(p.service[0].toUpperCase()+p.service.slice(1))}.</p><div class="card-bottom"><span>Public growth record · ${p.eligibility.revenueYear}</span><a class="arrow" href="/owners/${p.slug}/" aria-label="Read ${e(p.name)} profile">↗</a></div></div></article>`;}
const cards=arr=>`<div class="cards">${arr.map(card).join('')}</div>`;
const guideCards=arr=>`<div class="guide-grid">${arr.map(g=>`<article class="guide-card"><span class="eyebrow">${e(g.category)}</span><h3><a href="/resources/${g.slug}/">${e(g.title)}</a></h3><p>${e(g.description)}</p><a class="text-link" href="/resources/${g.slug}/">Read the guide <span aria-hidden="true">↗</span></a></article>`).join('')}</div>`;
function taxFeatured(){return `<section class="aside-box" aria-label="Featured tax strategist"><span class="eyebrow">Meet our tax advisory firm</span><h2><a href="/tax-strategists/">AE Tax Advisors</a></h2><p>Explore year-round tax planning for business owners and real estate investors. Discuss your entities, owner compensation, upcoming transactions, and the scope of an advisory engagement.</p>${button(BOOK,'Book an AE discovery call')}<p class="tiny">AE Tax Advisors owns and publishes Business Owner Index. Explore our advisory services alongside the businesses featured here.</p></section>`;}
function aeBanner(){return `<section class="ae-banner" aria-label="Our publisher · AE Tax Advisors"><div><span class="eyebrow">Owned and published by AE Tax Advisors</span><h2>You built the business.<br>Plan what comes next.</h2><p>Bring the business and the owner's tax picture into the same conversation. Explore entity decisions, owner compensation, documentation, and a practical planning calendar with AE.</p><a class="text-link" href="/resources/">Explore the owner planning library <span aria-hidden="true">↗</span></a></div><div class="ae-panel"><div class="ae-wordmark">AE<small>TAX ADVISORS</small></div><p>For owners ready to connect growth with a more organized tax plan.</p>${button(BOOK,'Book a discovery call','light')}<p class="ae-footnote">A discovery call is a scope-and-fit conversation. Services require an engagement.</p></div></section>`;}
const industryCopy={
 'Construction & home services':{intro:'Meet the founders behind builders, trade businesses, facility-service companies, and home-service platforms with a published growth record. These companies connect skilled work, project delivery, customer demand, and operational execution.',focus:['Job-level margin and working capital','Equipment records and financing decisions','Payroll, owner responsibilities, and project expansion'],guide:'equipment-purchase-planning'},
 'Marketing & agencies':{intro:'Explore the founders building agencies in search, creative services, performance marketing, and specialized client acquisition. Their businesses show different ways to turn expertise into a repeatable client service.',focus:['Retainer and project economics','Owner compensation and the delivery team','Collections, contractor payments, and growth spending'],guide:'owner-compensation-review'},
 'Software & AI':{intro:'Discover founders working across business software, applied AI, cybersecurity, and industry-specific technology. The collection brings together public growth records from businesses solving concrete operational problems.',focus:['Recurring revenue and cash runway','Hiring, product investment, and owner cash needs','Entity structure and future transactions'],guide:'entity-structure-review'},
 'Healthcare & wellness':{intro:'Meet founders building healthcare technology, remote-care tools, and wellness businesses. The directory describes their business activities from public sources and does not evaluate clinical outcomes or provide medical recommendations.',focus:['Revenue-cycle and collection visibility','Payroll, staffing, and documentation','Owner benefits and a repeatable planning cadence'],guide:'retirement-plan-design-conversation'},
 'Logistics & commerce':{intro:'Explore entrepreneurs building shipping platforms, fulfillment networks, warehouse services, and commerce infrastructure. Their companies operate where customer delivery, technology, inventory, and cash timing meet.',focus:['Working capital and customer collections','Warehouses, equipment, and operating cash','Multi-entity growth and transaction planning'],guide:'revenue-profit-and-owner-cash'},
 'Manufacturing & products':{intro:'Meet founders behind consumer products, industrial fabrication, building materials, and active-lifestyle equipment. Public profiles connect the people, the product category, and the business growth record.',focus:['Inventory and production cash needs','Asset records and capital spending','Margins, payroll, and owner distributions'],guide:'equipment-purchase-planning'},
 'Professional services':{intro:'Discover founders building consulting firms, staffing businesses, financial-service companies, and specialized advisory platforms. This collection focuses on the businesses and the people publicly associated with their growth.',focus:['Client profitability and cash collections','Owner work, payroll, and partner arrangements','Consistent books and an implementation calendar'],guide:'books-ready-for-tax-planning'},
 'Food & hospitality':{intro:'Meet founders behind food brands, restaurant concepts, and convenience retail. These profiles document the business category and published growth milestones, without substituting for customer due diligence.',focus:['Product and location economics','Inventory, payroll, and capital investment','Owner cash needs and expansion timing'],guide:'quarterly-tax-planning-agenda'},
 'Energy & infrastructure':{intro:'Explore founders building energy-service businesses, solar companies, and infrastructure-support platforms. The collection highlights public business information and growth records across a changing operating environment.',focus:['Project cash timing and financing','Equipment, documentation, and entity coordination','Transaction planning with specialized advisers'],guide:'acquisition-tax-diligence-questions'}
};
function aside(p){const relevant=industryCopy[p?.industry]?.guide||guides[0].slug;return `<aside aria-label="Related information"><div class="aside-box aside-dark"><span class="eyebrow">Our publisher · AE Tax Advisors</span><h2>Build your next chapter with AE.</h2><p>Tax planning starts with your business, your income, and the decisions ahead.</p>${button(BOOK,'Meet the AE team','light')}<p class="tiny">AE owns this publication. A business profile does not imply an AE client relationship.</p></div><div class="aside-box"><span class="eyebrow">Owner resources</span><div class="aside-links"><a href="/resources/${relevant}/">${e(guides.find(g=>g.slug===relevant)?.title||guides[0].title)} ↗</a><a href="/resources/tax-planning-for-million-dollar-business-owners/">Planning after $1 million in revenue ↗</a><a href="/get-featured/?request=update${p?'&owner='+encodeURIComponent(p.name):''}">Update or claim your profile ↗</a><a href="/editorial-standards/">How the index is researched ↗</a></div></div></aside>`;}
const featured=owners.slice(0,6);
write('/','The people behind million-dollar businesses','Explore a national directory of established business founders, company growth records, and owner resources. Owned and published by AE Tax Advisors.',`<div class="wrap"><section class="hero"><div><span class="eyebrow">The business owner index</span><h1>The people behind<br><em>million-dollar</em><br>businesses.</h1><p class="lede">Meet the founders. Discover what they built.<br>Discover established businesses and the founders behind them. Free profiles help businesses share their public story and get discovered.</p><form class="search-form" action="/directory/" method="get" role="search"><label class="skip" for="home-search">Search owners and companies</label><input id="home-search" name="q" placeholder="Search a name, company, or industry" type="search"><button class="button" type="submit">Explore <span aria-hidden="true">↗</span></button></form><div class="hero-note"><div class="proof-dots" aria-hidden="true"><span>MD</span><span>MK</span><span>CS</span></div><span class="tiny">Real businesses. Public sources. People worth knowing.</span></div></div><div class="hero-art"><span class="art-plus" aria-hidden="true">+</span><div class="hero-stack">${featured.slice(0,3).map(p=>`<a class="feature-plaque" href="/owners/${p.slug}/"><span class="plaque-icon" aria-hidden="true">${initials(p.name)}</span><span><strong class="plaque-name">${e(p.name)}</strong><span class="plaque-company">${e(p.company)} · ${e(p.role)}</span></span><span class="plaque-arrow" aria-hidden="true">↗</span></a>`).join('')}</div><span class="art-caption">The founders behind the names</span></div></section><div class="facts-strip"><div class="fact"><strong>${owners.length}</strong><span>founder profiles<br>in the launch index</span></div><div class="fact"><strong>${industries.length}</strong><span>industries<br>to explore</span></div><div class="fact"><strong>$1M+</strong><span>annual company revenue<br>eligibility focus</span></div><div class="fact"><strong>AE</strong><span>Tax Advisors<br>owner and publisher</span></div></div><section class="section"><div class="section-head"><div><span class="eyebrow">Inside the index</span><h2>Meet the business builders.</h2></div><a class="text-link" href="/directory/">View all profiles <span aria-hidden="true">↗</span></a></div>${cards(featured)}</section></div><section class="industry-section section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Find your world</span><h2>Built across every kind of business.</h2></div><a class="text-link" href="/industries/">Explore industries <span aria-hidden="true">↗</span></a></div><div class="industry-grid">${industries.map((ind,i)=>`<a class="industry-link" href="/industries/${slug(ind)}/"><span class="industry-num">${String(i+1).padStart(2,'0')}</span><span><span class="industry-title">${e(ind)}</span><span class="industry-count">${owners.filter(p=>p.industry===ind).length} founder profiles</span></span><span class="industry-arrow" aria-hidden="true">↗</span></a>`).join('')}</div></div></section><div class="wrap"><div class="section">${aeBanner()}</div><section class="section"><div class="section-head"><div><span class="eyebrow">The owner's next chapter</span><h2>Growth deserves a plan.</h2></div><a class="text-link" href="/resources/">All owner resources <span aria-hidden="true">↗</span></a></div>${guideCards(guides.slice(0,3))}</section><section class="join-strip"><div><h2>Your business has a story.</h2><p>Doing over $1 million in annual revenue? Put the person behind the company on the map.</p></div>${button('/get-featured/','Request a free profile')}</section></div>`,{schema:[{'@type':'WebSite','@id':BASE+'/#website',url:BASE,name:'Business Owner Index',publisher:{'@id':BASE+'/#publisher'}},{'@type':'Organization','@id':BASE+'/#publisher',name:'Business Owner Index',url:BASE,logo:BASE+'/assets/favicon.svg',parentOrganization:{'@type':'Organization',name:'AE Tax Advisors',url:AE}}]});
const SIZE=18;
for(let page=1;page<=Math.ceil(owners.length/SIZE);page++){
 const p=page===1?'/directory/':`/directory/page/${page}/`;
 const chunk=owners.slice((page-1)*SIZE,page*SIZE);
 const tools=page===1?`<div class="directory-tools" data-directory><div class="field"><label for="owner-search">Name, company, or keyword</label><input id="owner-search" type="search" placeholder="Find a business builder"></div><div class="field"><label for="industry-filter">Industry</label><select id="industry-filter"><option value="">All industries</option>${industries.map(x=>`<option>${e(x)}</option>`).join('')}</select></div><div class="field"><label for="location-filter">Location</label><select id="location-filter"><option value="">All locations</option>${locations.map(x=>`<option>${e(x)}</option>`).join('')}</select></div><div class="field"><label for="sort-filter">Sort profiles</label><select id="sort-filter"><option value="featured">Editorial order</option><option value="name">Owner name A–Z</option><option value="company">Company name A–Z</option></select></div></div>`:'';
 write(p,`Business owner directory${page===1?'':`, page ${page}`}`,`Browse established business founders and their companies. ${page===1?'Search by name, company, industry, or location.':`Directory page ${page}.`} Owned and published by AE Tax Advisors.`,`<div class="wrap"><section class="page-head">${bread([['The directory',page===1?null:'/directory/'],...(page===1?[]:[[`Page ${page}`,null]])])}<span class="eyebrow">People first. Business always.</span><h1>The directory${page===1?'.':` · ${page}`}</h1><p class="lede">The founders behind established companies. Explore their businesses, published growth records, and the industries they help shape.</p><p class="tiny">The $1 million eligibility focus refers to company revenue, not owner income. Historical evidence and its year are shown on each profile.</p></section>${tools}${taxFeatured()}<div class="results-meta"><span data-result-count>${owners.length} founder profiles</span><span data-results-note>Showing ${(page-1)*SIZE+1}–${Math.min(page*SIZE,owners.length)} of ${owners.length}</span></div><div class="cards" data-results>${chunk.map(card).join('')}</div><nav class="pagination" data-pages aria-label="Directory pages">${Array.from({length:Math.ceil(owners.length/SIZE)},(_,i)=>`<a href="${i===0?'/directory/':`/directory/page/${i+1}/`}" ${page===i+1?'aria-current="page"':''}>${i+1}</a>`).join('')}</nav><noscript><p>Search filters require JavaScript. All profiles remain available through the directory pages and industry collections.</p></noscript><div class="section">${aeBanner()}</div></div>`,{schema:[{'@type':'CollectionPage',url:BASE+p,name:`Business owner directory page ${page}`,mainEntity:{'@type':'ItemList',itemListElement:chunk.map((x,i)=>({'@type':'ListItem',position:(page-1)*SIZE+i+1,url:BASE+'/owners/'+x.slug+'/',name:x.name}))}}]});
}
for(const p of owners){
 const url='/owners/'+p.slug+'/',companyURL='/companies/'+p.companySlug+'/';
 const person={'@type':'Person','@id':BASE+url+'#person',name:p.name,url:BASE+url,description:p.summary,jobTitle:p.role,worksFor:{'@type':'Organization','@id':BASE+companyURL+'#company',name:p.company,url:BASE+companyURL}};
 const sourceList=`<ol class="source-list">${p.sources.map(s=>`<li><a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title)}</a></li>`).join('')}<li><a href="${p.eligibility.awardYear===2026?'https://inc5000.secure-platform.com/a/solicitations/104/home':'https://www.inc.com/sarah-lynch/apply-now-for-the-2025-inc-5000-list/91150132'}" target="_blank" rel="noopener noreferrer">${p.eligibility.awardYear} Inc. 5000 eligibility criteria</a></li></ol>`;
 const eligibility=`${p.eligibility.awardYear} Inc. 5000 inclusion is a historical eligibility signal. That edition's published criteria required at least $2 million in company revenue in ${p.eligibility.revenueYear}. This is a qualifying threshold, not an exact revenue figure, current-year estimate, or measure of the founder's income.`;
 const factRows=[['Business',`<a href="${companyURL}">${e(p.company)}</a>`],['Publicly reported role',e(p.role)],['Industry',`<a href="/industries/${slug(p.industry)}/">${e(p.industry)}</a>`],['Location',p.location==='United States'?'United States; specific location not confirmed':`<a href="/locations/${slug(p.location)}/">${e(p.location)}</a>`],['Profile basis','Publicly researched'],['Research date','October 9, 2026']].map(([label,value])=>`<div class="fact-row"><dt>${e(label)}</dt><dd>${value}</dd></div>`).join('');
 write(url,`${p.name}, ${p.company} founder profile`,`${p.name} of ${p.company}: business profile, industry context, and public growth evidence. A publicly researched feature owned and published by AE Tax Advisors.`,`<div class="wrap"><section class="page-head">${bread([['The directory','/directory/'],[p.name,null]])}<div class="profile-hero"><div><span class="eyebrow">The person behind the business</span><h1>${e(p.name)}</h1><p class="profile-role">${e(p.role)} · <a href="${companyURL}">${e(p.company)}</a></p><p class="lede">${e(p.service[0].toUpperCase()+p.service.slice(1))}.</p><div class="tags"><a class="tag" href="/industries/${slug(p.industry)}/">${e(p.industry)}</a><span class="tag">Publicly researched</span><span class="tag">Growth record: ${p.eligibility.revenueYear}</span></div></div><div class="profile-art" aria-hidden="true"><span class="monogram">${e(initials(p.name))}</span></div></div></section><div class="profile-layout"><article class="prose"><span class="eyebrow">Founder overview</span><h2>Meet ${e(p.name)}.</h2><p>${e(p.summary)}</p><p>${e(p.milestone)}</p><dl class="fact-table">${factRows}</dl><h2>The business behind the profile.</h2><p>${e(p.company)} is included in this directory for its work in ${e(p.service)} and its published growth record. Explore the <a href="${companyURL}">company page</a> for the business-focused overview, or browse <a href="/industries/${slug(p.industry)}/">other founders in ${e(p.industry.toLowerCase())}</a>.</p><h2>Revenue eligibility, with context.</h2><div class="note-box"><p>${e(eligibility)}</p></div><p class="tiny">Founder or executive status does not confirm a person's current ownership percentage. This page records the public role identified by its source. Exact current revenue and ownership are not independently audited by the directory.</p><h2>Public sources.</h2>${sourceList}<h2>Questions about ${e(p.name)}.</h2><div class="faq"><details><summary>Who is ${e(p.name)}?</summary><p>${e(p.summary)}</p></details><details><summary>What is ${e(p.company)} known for?</summary><p>The business is associated with ${e(p.service)}. Its public growth milestone is documented above.</p></details><details><summary>Does this feature mean ${e(p.name)} works with AE?</summary><p>No. This is a publicly researched directory profile. AE Tax Advisors presents the directory, and inclusion does not establish a client relationship or endorsement.</p></details><details><summary>How can the owner update this page?</summary><p><a href="/get-featured/?request=update&owner=${encodeURIComponent(p.name)}">Send a profile update request</a> with current public information and supporting sources. Identity and authority are reviewed before changes are published.</p></details></div><div class="button-row"><button class="button outline" data-copy-link type="button">Copy profile link</button>${button('/get-featured/?request=update&owner='+encodeURIComponent(p.name),'Request a correction','outline')}</div></article>${aside(p)}</div><section class="section"><div class="section-head"><div><span class="eyebrow">Continue exploring</span><h2>More business builders.</h2></div></div>${cards(owners.filter(x=>x.industry===p.industry&&x.slug!==p.slug).slice(0,3))}</section></div>`,{webPage:{mainEntity:person},schema:[person,breadcrumbSchema([['The directory','/directory/'],[p.name,url]])],lastmod:p.reviewedAt});
 write(companyURL,`${p.company}: company and founder overview`,`Explore ${p.company}, its publicly reported founder ${p.name}, its business category, and its published growth record. Owned and published by AE Tax Advisors.`,`<div class="wrap"><section class="page-head">${bread([['The directory','/directory/'],[p.company,null]])}<span class="eyebrow">The company in context</span><h1>${e(p.company)}</h1><p class="lede">${e(p.service[0].toUpperCase()+p.service.slice(1))}.</p><div class="tags"><a class="tag" href="/industries/${slug(p.industry)}/">${e(p.industry)}</a><span class="tag">Historical revenue eligibility</span></div></section><div class="profile-layout"><article class="prose"><h2>Company overview.</h2><p>${e(p.company)} is a business associated with ${e(p.service)}. Public reporting identifies <a href="/owners/${p.slug}/">${e(p.name)}</a> as its ${e(p.role.toLowerCase())}.</p><h2>Published growth milestone.</h2><p>${e(p.milestone)}</p><div class="note-box"><p>${e(eligibility)}</p></div><h2>The person behind the company.</h2><p>Learn more about the public role and research basis on <a href="/owners/${p.slug}/">${e(p.name)}'s founder profile</a>. Profile details are sourced rather than submitted as a claim of AE affiliation.</p><h2>Research and corrections.</h2>${sourceList}<p>The authorized company representative can <a href="/get-featured/?request=update">request an update</a>, add current sources, or ask the team to review a correction. A historical listing is not a guarantee of current financial performance.</p></article>${aside(p)}</div><div class="section">${aeBanner()}</div></div>`,{webPage:{mainEntity:{'@id':BASE+companyURL+'#company'}},schema:[{'@type':'Organization','@id':BASE+companyURL+'#company',name:p.company,url:BASE+companyURL,description:`Business associated with ${p.service}.`,...(/founder/i.test(p.role)?{founder:{'@id':BASE+url+'#person'}}:{})},breadcrumbSchema([['The directory','/directory/'],[p.company,companyURL]])],lastmod:p.reviewedAt});
}
write('/industries/','Explore business founders by industry','Browse founders across construction, software, healthcare, agencies, manufacturing, logistics, professional services, food, and energy.',`<div class="wrap"><section class="page-head">${bread([['Industries',null]])}<span class="eyebrow">Built across the economy</span><h1>Find your industry.</h1><p class="lede">Different businesses. Different operating challenges. The same drive to build something that lasts.</p></section><div class="collection-grid">${industries.map(ind=>`<article class="collection-card"><span class="eyebrow">${owners.filter(p=>p.industry===ind).length} founder profiles</span><h2><a href="/industries/${slug(ind)}/">${e(ind)}</a></h2><p>${e(industryCopy[ind].intro)}</p><a class="text-link" href="/industries/${slug(ind)}/">Explore the collection <span aria-hidden="true">↗</span></a></article>`).join('')}</div><div class="section">${aeBanner()}</div></div>`);
for(const ind of industries){const collection=owners.filter(p=>p.industry===ind),copy=industryCopy[ind];write(`/industries/${slug(ind)}/`,`${ind} business owners and founders`,copy.intro,`<div class="wrap"><section class="page-head">${bread([['Industries','/industries/'],[ind,null]])}<span class="eyebrow">${collection.length} business builders</span><h1>${e(ind)}.</h1><p class="lede">${e(copy.intro)}</p></section>${cards(collection)}<section class="section"><div class="profile-layout"><article class="prose"><span class="eyebrow">AE owner planning perspective</span><h2>Questions for the next stage.</h2><p>For owners in this industry, a useful planning conversation connects the operating model with the owner's tax and cash picture. The items below are general discussion topics, not conclusions about the featured businesses.</p><ul>${copy.focus.map(x=>`<li>${e(x)}</li>`).join('')}</ul><p><a href="/resources/${copy.guide}/">Read the relevant owner planning guide</a>, then bring your own financial statements and goals to an adviser.</p></article>${aside({industry:ind})}</div></section></div>`,{schema:[{'@type':'CollectionPage',name:ind,mainEntity:{'@type':'ItemList',itemListElement:collection.map((p,i)=>({'@type':'ListItem',position:i+1,name:p.name,url:BASE+'/owners/'+p.slug+'/'}))}}]});}
const cityCollections=locations.filter(loc=>owners.filter(p=>p.location===loc).length>=2);
write('/locations/','Business founders by location','Explore publicly researched founder profiles with a confirmed city in the source record. Browse the national directory for all owners.',`<div class="wrap"><section class="page-head">${bread([['Locations',null]])}<span class="eyebrow">Where businesses take shape</span><h1>Local roots. National ambition.</h1><p class="lede">Browse city collections with multiple founder profiles. Location is included only when the research supports it; a company can serve customers far beyond its home city.</p></section><div class="collection-grid">${cityCollections.map(loc=>`<article class="collection-card"><span class="eyebrow">${owners.filter(p=>p.location===loc).length} founder profiles</span><h2><a href="/locations/${slug(loc)}/">${e(loc)}</a></h2><p>Explore the companies and publicly reported founders in this collection.</p><a class="text-link" href="/locations/${slug(loc)}/">View the collection <span aria-hidden="true">↗</span></a></article>`).join('')}</div><div class="section">${button('/directory/','Explore the national directory')}</div></div>`);
for(const loc of locations){const collection=owners.filter(p=>p.location===loc);const indexable=collection.length>=2;write(`/locations/${slug(loc)}/`,`${loc} business owners and founders`,`Explore ${collection.length} publicly researched founder ${collection.length===1?'profile':'profiles'} associated with ${loc}, including company context and public growth records.`,`<div class="wrap"><section class="page-head">${bread([['Locations','/locations/'],[loc,null]])}<span class="eyebrow">Business builders in ${e(loc)}</span><h1>${e(loc)}.</h1><p class="lede">Discover the people and businesses in this ${collection.length===1?'growing':'local'} collection. Profiles link to their research sources and distinguish historical revenue evidence from current financial performance.</p></section>${cards(collection)}<div class="section">${button('/directory/','Browse all founders','outline')}</div></div>`,{indexable});}
write('/resources/','Owner planning library, owned and published by AE Tax Advisors','Practical tax-planning agendas, documentation checklists, and financial questions for owners of established businesses. Owned and published by AE Tax Advisors.',`<div class="wrap"><section class="page-head">${bread([['Owner resources',null]])}<span class="eyebrow">Owned and published by AE Tax Advisors</span><h1>Growth deserves a plan.</h1><p class="lede">Practical questions, clear preparation, and a more organized conversation about the business you built.</p><p class="tiny">General educational resources. A specific recommendation requires review of your circumstances.</p></section>${guideCards(guides)}<div class="section">${aeBanner()}</div></div>`);
for(const g of guides){const url='/resources/'+g.slug+'/';write(url,g.title,g.description,`<div class="wrap"><section class="page-head article-head">${bread([['Owner resources','/resources/'],[g.category,null]])}<span class="eyebrow">${e(g.category)} · AE owner planning library</span><h1>${e(g.title)}</h1><p class="lede">${e(g.description)}</p><div class="article-meta"><span>Published by Business Owner Index</span><span>October 9, 2026</span><span>4 minute read</span></div></section><div class="article-layout"><article class="prose"><p>${e(g.intro)}</p>${g.sections.map(s=>`<h2>${e(s.title)}</h2><p>${e(s.text)}</p>`).join('')}<h2>Bring this to the conversation.</h2><ul>${g.checklist.map(x=>`<li>${e(x)}</li>`).join('')}</ul><h2>Three questions worth asking.</h2><ol>${g.questions.map(x=>`<li>${e(x)}</li>`).join('')}</ol><h2>Turn the discussion into a next step.</h2><p>Ask for a written action list that identifies what should happen, who is responsible, and when the team should review the result. Keep supporting documents with the decision so the books, payroll, and return preparation can follow the same facts.</p><div class="note-box"><p>AE Tax Advisors presents this resource library. To discuss scope and fit for your own business, <a href="${e(BOOK)}">book a discovery call</a>. Directory inclusion is separate from purchasing services.</p></div><h2>Reference and applicability.</h2><p><a href="${e(g.source)}" target="_blank" rel="noopener noreferrer">Related IRS guidance</a>. The checklist and meeting agenda are editorial preparation tools, not an IRS-prescribed procedure. Tax treatment, elections, and deadlines depend on the facts and applicable law. This page does not establish an advisory relationship.</p></article>${aside()}</div><section class="section">${guideCards([...guides.filter(x=>x.slug!==g.slug&&x.category===g.category),...guides.filter(x=>x.slug!==g.slug&&x.category!==g.category)].slice(0,3))}</section></div>`,{article:true,schema:[{'@type':'Article',headline:g.title,description:g.description,datePublished:'2026-10-09',dateModified:'2026-10-09',author:{'@type':'Organization',name:'Business Owner Index'},publisher:{'@id':BASE+'/#publisher'},mainEntityOfPage:BASE+url},breadcrumbSchema([['Owner resources','/resources/'],[g.title,url]])]});}
write('/ae-tax-advisors/','AE Tax Advisors, the team behind Business Owner Index','Discover why AE Tax Advisors presents Business Owner Index and explore tax-planning conversations for established business owners.',`<div class="wrap"><section class="page-head">${bread([['AE Tax Advisors',null]])}<span class="eyebrow">The owner and publisher</span><h1>You built the business.<br>Plan the next chapter.</h1><p class="lede">Business Owner Index is owned and published by AE Tax Advisors to celebrate established founders and make useful owner-planning conversations easier to start.</p></section><div class="profile-layout"><article class="prose"><h2>Connect the company and the owner.</h2><p>Business growth changes the decisions on an owner's desk: entity structure, compensation, tax payments, asset purchases, documentation, acquisitions, and personal cash needs. AE's discovery process starts with what the business does and what the owner wants to accomplish.</p><h2>A practical starting point.</h2><p>Bring a description of the business, its entities, approximate annual revenue and profit, current advisers, and the decisions ahead. The discovery call helps establish whether the team's services fit the request and what an engagement would need to cover.</p><ul><li>Entity and owner-income planning conversations</li><li>Business and personal return coordination</li><li>Documentation and implementation priorities</li><li>Asset and cost-segregation questions where relevant</li></ul><div class="button-row">${button(BOOK,'Book an AE discovery call')}${button(AE+'/?utm_source=businessownerindex&utm_medium=directory','Visit AE Tax Advisors','outline')}</div><h2>Free profiles and advisory services are separate.</h2><p>A directory profile does not require a tax engagement. Publicly researched features do not represent the subjects as clients. AE Tax Advisors owns and publishes Business Owner Index. This publication introduces our advisory services and gives established businesses a place to be discovered.</p><h2>Start with a useful question.</h2><p>Explore the <a href="/resources/">owner planning library</a> for checklists you can bring to a conversation. The right next step depends on your actual facts, not your revenue milestone alone.</p></article>${aside()}</div></div>`);
write('/get-featured/','Get featured or update a business owner profile','Request a free founder profile for a business exceeding $1 million in annual revenue, or submit an authorized update to an existing profile.',`<div class="wrap"><section class="page-head">${bread([['Get featured',null]])}<span class="eyebrow">Put the person behind the company on the map</span><h1>Your business has a story.</h1><p class="lede">Request a free profile, nominate a founder, or update an existing page. The index focuses on businesses exceeding $1 million in annual company revenue.</p></section><div class="form-layout"><form class="submission-form" data-submission><div class="form-grid"><div class="field"><label for="name">Owner or founder name</label><input id="name" name="name" required maxlength="120" autocomplete="name"></div><div class="field"><label for="role">Public role</label><input id="role" name="role" required maxlength="120" placeholder="Founder, owner, or co-founder"></div><div class="field"><label for="company">Company name</label><input id="company" name="company" required maxlength="160" autocomplete="organization"></div><div class="field"><label for="website">Company website</label><input id="website" name="website" type="url" required placeholder="https://" maxlength="400"></div><div class="field"><label for="email">Business email</label><input id="email" name="email" type="email" required maxlength="160" autocomplete="email"></div><div class="field"><label for="location">City and state</label><input id="location" name="location" required maxlength="120"></div><div class="field"><label for="revenue">Annual company revenue, kept private</label><select id="revenue" name="revenue" required><option value="">Choose a band</option><option>Over $1M to $5M</option><option>Over $5M to $10M</option><option>Over $10M to $25M</option><option>Over $25M to $50M</option><option>Over $50M</option><option>Update or removal request; revenue not supplied</option></select></div><div class="field"><label for="request">What would you like?</label><select id="request" name="request"><option>New founder profile</option><option>Nominate a founder</option><option>Update an existing profile</option><option>Correct or remove a profile</option></select></div><div class="field full"><label for="story">Business story and public source links</label><textarea id="story" name="story" required maxlength="2500" placeholder="What does the business do? Include public links supporting the founder's role and business growth. Do not attach tax returns or private financial documents."></textarea></div></div><label class="check-field"><input type="checkbox" required><span>I am authorized to submit these profile details, or I am submitting a nomination using public information. I understand that publication is reviewed and does not establish an AE tax engagement.</span></label><button class="button" type="submit">Prepare profile request <span aria-hidden="true">↗</span></button><p class="tiny">This form prepares an email in your own email app. Nothing is submitted until you send that email. Revenue bands are for the review team and are not automatically published.</p><div class="form-status" id="profile-draft" data-draft-result hidden><p>Your email draft is ready. Open it, review it, and send it to the AE team.</p><a class="button outline" data-email-draft href="mailto:team@aetaxadvisors.com">Open email draft ↗</a></div><noscript><p>Email your profile request to <a href="mailto:team@aetaxadvisors.com?subject=Business%20Owner%20Index%20profile%20request">team@aetaxadvisors.com</a>. Include your name, company, website, role, location, and public sources.</p></noscript></form><div><div class="statement"><strong>Recognition without a sales requirement.</strong><p>There is no directory listing fee and no requirement to purchase AE services.</p></div><div class="statement"><strong>A profile built around real information.</strong><p>Your public role, company, business story, and sources. No invented rankings, testimonials, or financial claims.</p></div><div class="statement"><strong>A page that can grow with you.</strong><p>Authorized updates can add current milestones, clarify your role, and correct outdated information.</p></div><div class="statement"><strong>Revenue is a qualification, not the headline.</strong><p>We focus on company revenue above $1 million. Private financial material is not required through this form.</p></div><p class="tiny">Read our <a href="/editorial-standards/">editorial standards</a> and <a href="/privacy/">privacy information</a> before sending a request.</p></div></div></div>`,{indexable:true});
const staticPages={
 '/about/':{title:'A record of the people building established businesses',desc:'The purpose, audience, and ownership of Business Owner Index.',body:`<h2>Business owners deserve to be known for what they build.</h2><p>A company name can hide the people behind it. Business Owner Index brings those people into view through founder profiles, company context, and public growth records.</p><h2>Our focus.</h2><p>The directory is built for established businesses with annual company revenue above $1 million. A profile can be supported by a dated public revenue statement, a qualifying growth-list record, or a reviewed owner submission. The evidence basis is identified rather than treated as an independently audited current figure.</p><h2>Owned and published by AE Tax Advisors.</h2><p>AE Tax Advisors owns and publishes Business Owner Index. Business Owner Index promotes established businesses through sourced founder and company profiles. That connection is visible throughout the site. Profiles and advisory services are separate; inclusion does not imply that an owner is an AE client or endorses AE.</p><h2>Two ways into the index.</h2><p>Our launch profiles are publicly researched. Owners can also request a free profile or submit an authorized update. We review the person's role, company identity, source support, and revenue eligibility before publication.</p><p><a href="/get-featured/">Tell us about your business</a> or <a href="/directory/">explore the founders already in the index</a>.</p>`},
 '/editorial-standards/':{title:'Editorial standards and revenue eligibility',desc:'How founder profiles are sourced, qualified, labeled, corrected, and connected to the owner and publisher.',body:`<h2>Public facts, identifiable sources.</h2><p>Profiles name their sources and identify the basis for publication. Publicly researched pages are not described as owner-approved, interviewed, or claimed unless that status has actually been established. Summaries are original and do not republish a source article.</p><h2>The million-dollar focus.</h2><p>The eligibility target is more than $1 million in annual company revenue. Revenue is not profit, valuation, funding, systemwide franchise sales, or the owner's personal income. A public record must identify a relevant business and a dated revenue basis. An Inc. 5000 record can support historical eligibility when the edition's published minimum revenue exceeds the threshold.</p><h2>Historical evidence is not a current estimate.</h2><p>The launch uses dated growth-list records. Its qualifying minimum is shown with the revenue year and is not presented as the company's exact revenue. When a source does not confirm a city, the profile does not invent one. A founder's role does not confirm current equity ownership.</p><h2>Owner submissions.</h2><p>Submitted profiles are reviewed for identity, authority, source support, and eligibility. Self-reported revenue is labeled as such and is not silently upgraded to independently verified revenue. Do not send tax returns, identification documents, or confidential financial records through the profile request form.</p><h2>Visible ownership.</h2><p>AE Tax Advisors owns Business Owner Index and publishes the owner resource library. AE advisory sections introduce the publisher’s own services. Featuring a person does not establish an AE client relationship, endorsement, recommendation, or award. We do not sell favorable profile claims or require an advisory engagement for a free listing.</p><h2>Corrections and removals.</h2><p>An authorized person can request a correction, update, or removal through the <a href="/get-featured/">profile request page</a>. The team reviews the request and its supporting information before changing the published record. No unsupported response-time promise is made.</p><h2>Publishing pace.</h2><p>Pages are published when the facts support a useful profile. A numerical growth target does not replace source review, duplicate checks, or substantive business information.</p>`},
 '/privacy/':{title:'Privacy and profile information',desc:'How Business Owner Index handles public profile information and visitor-submitted profile requests.',body:`<h2>Public directory information.</h2><p>The directory displays public business and founder information with sources. It does not publish personal home addresses, private contact details, tax returns, or confidential financial records as part of an owner profile.</p><h2>Profile requests.</h2><p>The request form prepares an email draft in your email application. Its fields are not sent to a website backend when you click Prepare profile request. Information is transmitted to the AE team only if you choose to send the email. A submitted revenue band is for review and is not automatically displayed on a profile.</p><h2>Website operation.</h2><p>The launch website does not add advertising trackers or a third-party analytics script. Its hosting provider may process routine request information to deliver and protect the site. Directory search uses a public search index in your browser. Search terms may appear in the page address and routine hosting request logs.</p><h2>External sites.</h2><p>Links to source publications and AE's website lead to sites with their own privacy practices. A discovery booking occurs on AE's website, under the practices described there.</p><h2>Updates and privacy requests.</h2><p>Contact <a href="mailto:team@aetaxadvisors.com?subject=Business%20Owner%20Index%20privacy%20request">team@aetaxadvisors.com</a> to ask about information you submitted or to request review of public profile details. Please identify the page and the requested change without emailing unnecessary sensitive documents.</p>`},
 '/terms/':{title:'Terms and directory disclosures',desc:'Directory use, ownership, public-source limitations, and general educational resource disclosures.',body:`<h2>Directory purpose.</h2><p>Business Owner Index is a publication and business directory owned and published by AE Tax Advisors. Information is provided for general reference and may change after the source was published or the profile was researched.</p><h2>No implied relationship or award.</h2><p>A profile does not mean the featured business or person is a client, has approved the page, endorses AE, or has received a directory award. Publicly researched profiles are labeled. Third-party growth recognition is attributed to its source rather than represented as an award issued by this directory.</p><h2>Revenue and ownership.</h2><p>Historical qualifying revenue thresholds are not exact or current financial statements. Revenue is not the owner's income. A reported founder or executive role does not establish current ownership or equity percentage. Perform your own due diligence before relying on information for a business decision.</p><h2>Educational resources.</h2><p>Owner resources contain general information and discussion checklists. They are not individualized tax, legal, investment, or accounting advice. Applicable treatment depends on facts and law. Viewing a page, submitting a profile, or booking a discovery call does not create a professional engagement.</p><h2>Corrections.</h2><p>The team can review authorized update, correction, or removal requests sent through the <a href="/get-featured/">profile request page</a>. Sources, company names, and third-party marks belong to their respective owners; the directory does not claim affiliation with a source publication.</p>`}
};
for(const [url,p]of Object.entries(staticPages))write(url,p.title,p.desc,`<div class="wrap"><section class="page-head">${bread([[p.title,null]])}<span class="eyebrow">Behind the index</span><h1>${e(p.title)}</h1><p class="lede">${e(p.desc)}</p></section><div class="article-layout"><article class="prose">${p.body}</article>${aside()}</div></div>`);
write('/tax-strategists/','Tax strategist for business owners — Featured AE Tax Advisors','Explore AE Tax Advisors, the publisher’s tax advisory firm on Business Owner Index, and prepare for a business owner tax planning conversation.',`<div class="wrap"><section class="page-head"><span class="eyebrow">Business owner advisory</span><h1>Find a tax strategist for your next chapter.</h1><p class="lede">Tax planning works best when the business, its owners, and upcoming decisions are considered together.</p></section>${taxFeatured()}<article class="prose"><h2>Start with the work you need.</h2><p>Bring an outline of your entities, ownership, states, current tax preparation team, and the decisions ahead. Ask AE about planning, implementation responsibilities, review cadence, and written deliverables.</p><h2>Questions for your discovery call.</h2><ul><li>Who will lead the engagement, and what credentials do they hold?</li><li>Does the proposed scope cover your business and personal tax picture?</li><li>Which recommendations are delivered in writing?</li><li>Who coordinates with your existing preparer and completes each action?</li><li>What fees, deadlines, and ongoing reviews are included?</li></ul><h2>Meet the company behind the directory.</h2><p>AE Tax Advisors owns and publishes Business Owner Index. This page introduces the publisher’s own tax advisory firm. Founder profiles do not establish an AE client relationship.</p><p><a href="https://www.aetaxadvisors.com/" >Review AE’s official website</a> and confirm the responsible professionals, current services, and engagement scope directly.</p></article><div class="section">${aeBanner()}</div></div>`,{schema:[{'@type':'CollectionPage',name:'Featured tax strategist for business owners',url:BASE+'/tax-strategists/',mainEntity:{'@type':'ItemList',itemListElement:[{'@type':'ListItem',position:1,name:'AE Tax Advisors',url:AE}]}}]});
const promotionArticles=[
{slug:'prepare-a-founder-profile',title:'How to prepare a useful founder profile',intro:'A useful founder profile tells a reader who the person is, what the company does, and which public facts support the story. Begin with identity and business context before adding awards or growth milestones.',sections:[['Make the identity easy to confirm','Use the public professional name, exact company name, and a clear role. If a founder now holds a different position, distinguish founding history from the present role. Provide the company website and a public biography or announcement supporting the description. A role does not establish an ownership percentage.'],['Describe the business in concrete terms','Explain the product or service, the customers it serves, and the problem it addresses. Replace broad claims such as industry-leading with a specific description a reader can evaluate. A short account of the operating business is more useful than a string of promotional adjectives.'],['Attach dates to milestones','For each growth recognition, launch, acquisition, or expansion, provide the source and date. Distinguish a historical company revenue threshold from exact current revenue. Do not use financing, valuation, or total franchise-system sales as substitutes for the company’s own revenue.'],['Prepare an authorized update','Keep a record of the profile URL, proposed wording, and the source supporting each change. Send public information through the update process; avoid tax returns, account details, and private customer information. An editor may need to reconcile conflicting sources before publishing.']]},
{slug:'share-your-business-directory-profile',title:'How to put a business directory profile to work',intro:'A directory profile gives customers, partners, and professional contacts another place to understand the business. Use it as a factual introduction that complements the company’s own website.',sections:[['Give the reader a reason to open it','Share the profile when it helps answer a real question: who founded the business, what the company does, or which milestone was publicly reported. Add a sentence explaining why the profile matters to that conversation. Avoid sending a bare link as a substitute for a useful introduction.'],['Check the record before sharing','Read the role, company description, location, and dates. A historic announcement may remain accurate as history while needing a current update. Request a correction with a source rather than circulating wording you know is outdated.'],['Use recognition in its original context','Attribute third-party awards to the issuing organization and the actual year. A directory feature is not an independent award, a license check, or proof that AE advises the company. A public profile can promote a business without implying those relationships.'],['Measure meaningful interest','If you share the profile in a newsletter or professional introduction, consider the replies, relevant inquiries, and resulting conversations. Page views alone do not establish qualified demand. Keep the company website as the destination for current service details and official contact information.']]},
{slug:'read-public-company-growth-records',title:'How to read a company growth record without overstating it',intro:'A growth-list appearance can be useful business context, but it answers a narrower question than a current financial statement. Read the edition, measurement period, eligibility rules, and source together.',sections:[['Separate the period from the publication date','An award announced this year may measure revenue from an earlier period. State both the edition and the revenue year when the source supports them. A historical threshold does not become a current estimate merely because the profile was reviewed recently.'],['Keep revenue, funding, and owner income distinct','Sales, profit, cash flow, valuation, and financing describe different parts of a business. None automatically tells you the founder’s personal income. If the public source establishes only a qualifying threshold, preserve that limit instead of filling the gap with an estimate.'],['Ask what the source actually confirms','A company announcement can support the announcement and the role it names. It is not an independent audit of financial performance. When records conflict, identify the disputed fact and seek a more direct or more recent public source.'],['Use the record as a starting point','A profile can help you identify a business and understand its public history. Before making a commercial decision, review the company’s current information and perform the diligence appropriate to that decision. Growth recognition alone is not a recommendation to buy, invest, or hire.']]}
];
write('/business-promotion/','Business promotion and founder profile resources','Prepare, update, and share a factual founder or company profile with Business Owner Index.',`<div class="wrap"><section class="page-head"><span class="eyebrow">Business visibility</span><h1>Give your business a useful public introduction.</h1><p class="lede">Business Owner Index promotes established businesses through sourced founder and company profiles. AE Tax Advisors owns and publishes this directory.</p></section><div class="guide-grid">${promotionArticles.map(a=>`<article class="guide-card"><h2><a href="/business-promotion/${a.slug}/">${e(a.title)}</a></h2><p>${e(a.intro)}</p></article>`).join('')}</div><div class="section">${button('/get-featured/','Request or update a free profile')}</div></div>`);
for(const a of promotionArticles)write('/business-promotion/'+a.slug+'/',a.title,a.intro,`<div class="wrap"><section class="page-head">${bread([['Business promotion','/business-promotion/'],[a.title,null]])}<span class="eyebrow">Business Owner Index editorial guide</span><h1>${e(a.title)}</h1><p class="lede">${e(a.intro)}</p></section><div class="profile-layout"><article class="prose">${a.sections.map(([h,t])=>`<h2>${e(h)}</h2><p>${e(t)}</p>`).join('')}<h2>Put the guide to work.</h2><p><a href="/get-featured/">Request a free profile or an authorized update</a>, review our <a href="/editorial-standards/">sourcing standards</a>, or <a href="/people/">browse the people already featured</a>. The guidance here is an editorial preparation process, not a promise of traffic or search rankings.</p></article>${aside()}</div></div>`,{article:true,schema:[{'@type':'Article',headline:a.title,datePublished:'2026-10-09',dateModified:'2026-10-09',author:{'@type':'Organization',name:'Business Owner Index'},publisher:{'@id':BASE+'/#publisher'}}]});
write('/people/','Business founders A–Z: people and companies','Find publicly researched founders by name, with their companies, reported roles, and links to source-supported profiles.',`<div class="wrap"><section class="page-head"><span class="eyebrow">People A–Z</span><h1>Find the person behind the company.</h1><p class="lede">An alphabetical reference to ${owners.length} publicly researched business profiles. Each profile links to the company, historical growth context, and its public sources.</p></section><article class="prose"><ul>${[...owners].sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<li><a href="/owners/${p.slug}/">${e(p.name)}</a> — ${e(p.role)}, <a href="/companies/${p.companySlug}/">${e(p.company)}</a></li>`).join('')}</ul></article><div class="section">${button('/directory/','Search and filter profiles')}</div></div>`);

write('/sitemap/','All founder profiles, companies, and resources','Browse every founder profile, company page, industry collection, and owner planning resource in Business Owner Index.',`<div class="wrap"><section class="page-head"><span class="eyebrow">The complete index</span><h1>Every page. One place.</h1></section><article class="prose"><h2>Founder profiles and companies.</h2><ul>${[...owners].sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<li><a href="/owners/${p.slug}/">${e(p.name)}</a> · <a href="/companies/${p.companySlug}/">${e(p.company)}</a></li>`).join('')}</ul><h2>Industries.</h2><ul>${industries.map(x=>`<li><a href="/industries/${slug(x)}/">${e(x)}</a></li>`).join('')}</ul><h2>Owner resources.</h2><ul>${guides.map(g=>`<li><a href="/resources/${g.slug}/">${e(g.title)}</a></li>`).join('')}</ul></article><div class="section">${button('/directory/','Search the directory')}</div></div>`);
// Each sitemap remains below the 50,000 URL limit as the directory grows.
for(let i=0;i<pages.length;i+=10000){const part=pages.slice(i,i+10000);fs.writeFileSync(path.join(out,`sitemap-${i/10000+1}.xml`),`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${part.map(p=>`<url><loc>${BASE+p.path}</loc><lastmod>${p.lastmod}</lastmod></url>`).join('')}</urlset>`);}
fs.writeFileSync(path.join(out,'sitemap.xml'),`<?xml version="1.0" encoding="UTF-8"?><sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${Array.from({length:Math.ceil(pages.length/10000)},(_,i)=>`<sitemap><loc>${BASE}/sitemap-${i+1}.xml</loc></sitemap>`).join('')}</sitemapindex>`);
fs.writeFileSync(path.join(out,'robots.txt'),`User-agent: *\nAllow: /\nSitemap: ${BASE}/sitemap.xml\n`);
fs.writeFileSync(path.join(out,'llms.txt'),`# Business Owner Index\n\nNational directory of publicly researched founders associated with established companies. Owned and published by AE Tax Advisors.\n\n- Directory: ${BASE}/directory/\n- Industries: ${BASE}/industries/\n- Resources: ${BASE}/resources/\n- Editorial standards: ${BASE}/editorial-standards/\n- Owner and publisher: ${BASE}/ae-tax-advisors/\n- Sitemap: ${BASE}/sitemap.xml\n\nHistorical qualifying revenue thresholds do not establish current or exact revenue, personal income, or current equity ownership. Inclusion does not imply an AE client relationship or endorsement.\n`);
fs.writeFileSync(path.join(out,'assets/search-index.json'),json(owners.map(p=>({slug:p.slug,name:p.name,company:p.company,companySlug:p.companySlug,industry:p.industry,location:p.location,service:p.service,revenueYear:p.eligibility.revenueYear}))));
const notFound=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page not found | Business Owner Index</title><meta name="robots" content="noindex"><link rel="stylesheet" href="/assets/site.css"></head><body>${nav('/404/')}<main class="wrap page-head" id="main"><span class="eyebrow">Page not found</span><h1>This page is not in the index.</h1><p>Find a founder, company, or owner resource in the directory.</p>${button('/directory/','Explore the directory')}</main>${footer()}<script src="/assets/site.js" defer></script></body></html>`;
fs.writeFileSync(path.join(out,'404.html'),notFound);
fs.writeFileSync(path.join(root,'data/build-report.json'),JSON.stringify({owners:owners.length,companies:owners.length,industries:industries.length,indexableLocations:cityCollections.length,resources:guides.length,indexablePages:pages.length,totalHtmlPages:pages.length+locations.length-cityCollections.length+1,sourceHash:crypto.createHash('sha256').update(JSON.stringify(owners)).digest('hex'),generatedAt:new Date().toISOString()},null,2)+'\n');
console.log(JSON.stringify({owners:owners.length,companies:owners.length,indexablePages:pages.length,totalHtmlPages:pages.length+locations.length-cityCollections.length+1}));

